import sys; sys.path.insert(0,'/tmp/claude-0/rip'); from est import *
C='DIAG'
E(C,'M1-Z01','Che cos’è una diagnosi energetica',[CL("Diagnosi, APE o sistema di gestione?","Seleziona una caratteristica, poi lo strumento a cui appartiene.",["Diagnosi energetica","Attestato di prestazione energetica","Sistema di gestione ISO 50001"],[
 ["Valuta interventi con risparmi e costi sull’intero sito produttivo",0,"È il risultato tipico della diagnosi."],["Classifica l’edificio in condizioni standard",1,"L’APE certifica l’edificio in condizioni convenzionali."],
 ["Prevede obiettivi annuali, audit interni e riesame della direzione",2,"È un sistema di gestione continuo."],["Si esegue ogni quattro anni per gli obbligati",0,"Periodicità dell’art. 8."],
 ["Serve per vendere o affittare un immobile",1,"È il campo dell’APE."],["Richiede la certificazione di parte terza del sistema",2,"Riguarda la ISO 50001."]],
 "Sei caratteristiche. Attribuiscile alla diagnosi energetica, all’attestato di prestazione energetica o al sistema di gestione dell’energia.","D.lgs. 102/2014 · UNI CEI EN 16247-1 · UNI CEI EN ISO 50001")])
E(C,'M1-Z02','I criteri minimi dell’Allegato 2 al D.lgs. 102/2014',[SC("La diagnosi fatta sulle bollette","Un consulente propone una diagnosi basata solo sulle bollette mensili di energia elettrica e gas, senza misure né profili di carico, con interventi valutati solo con il tempo di ritorno.",[
 ("La diagnosi rispetta i criteri minimi?",[["No: servono dati operativi misurati e tracciabili e, per l’elettricità, profili di carico",True,"Corretto: è il primo criterio dell’Allegato 2."],["Sì, le bollette sono dati ufficiali",False,"Non bastano a ripartire i consumi per uso."],["Sì, se il consulente è certificato",False,"La certificazione non sostituisce i criteri minimi."]]),
 ("Come vanno valutati gli interventi?",[["Con l’analisi del costo del ciclo di vita, quando possibile, e non solo con il tempo di ritorno semplice",True,"Corretto: l’Allegato 2 lo richiede."],["Solo con il tempo di ritorno",False,"È un indicatore parziale."],["Senza valutazione economica",False,"La valutazione economica è necessaria."]]),
 ("Che cosa chiedi al consulente?",[["Un piano di misure sulle utenze significative e un modello energetico per aree funzionali",True,"Corretto: servono a costruire una diagnosi conforme."],["Uno sconto",False,"Non risolve la conformità."],["Di firmare comunque il rapporto",False,"Il rapporto sarebbe non conforme."]])],
 "Dati misurati e profili di carico, modello energetico per aree funzionali e analisi del ciclo di vita: senza questi elementi una diagnosi non rispetta i criteri minimi.","Una proposta di diagnosi molto semplificata. Valutane la conformità.","D.lgs. 102/2014, Allegato 2")])
E(C,'M1-Z03','Chi esegue la diagnosi',[SC("Il tecnico interno","Un’impresa obbligata vuole far eseguire la diagnosi al proprio responsabile tecnico, ingegnere esperto ma non certificato.",[
 ("La diagnosi sarà valida?",[["No: per gli obbligati serve un soggetto certificato, come un EGE secondo la UNI CEI 11339",True,"Corretto: ESCo, EGE o auditor certificati."],["Sì, basta la laurea in ingegneria",False,"La norma richiede la certificazione."],["Sì, se firma il legale rappresentante",False,"Non sostituisce la certificazione."]]),
 ("Qual è una soluzione?",[["Il tecnico ottiene la certificazione EGE, oppure si affianca a un soggetto certificato che firma la diagnosi",True,"Corretto: le competenze interne restano preziose."],["Si rinvia la diagnosi",False,"La scadenza va rispettata."],["Si usa la diagnosi di quattro anni prima",False,"La diagnosi va rifatta."]]),
 ("L’impresa ha un sistema ISO 50001 certificato. Cambia qualcosa?",[["Sì: è esentata se il sistema comprende una diagnosi conforme ai criteri minimi",True,"Corretto."],["No, nessuna esenzione",False,"L’esenzione esiste."],["È esentata anche senza diagnosi nel sistema",False,"Il sistema deve includere la diagnosi."]])],
 "Soggetti certificati per eseguire le diagnosi, competenze interne valorizzate, esenzione con ISO 50001 solo se il sistema include la diagnosi.","Chi può firmare la diagnosi? Valuta le opzioni.","Art. 8 D.lgs. 102/2014")])
E(C,'M1-Z04','L’obbligo di diagnosi energetica (art. 8 D.lgs. 102/2014)',[LB("Laboratorio · Chi è obbligato?","Verifica l’obbligo di diagnosi per tre imprese clienti.",[
  ["Impresa A","180 occupati, fatturato 62 milioni, bilancio 48 milioni"],["Impresa B","310 occupati, fatturato 40 milioni"],["Impresa C","90 occupati, iscritta nell’elenco CSEA delle imprese a forte consumo di energia"],["Impresa D","120 occupati, fatturato 30 milioni, non iscritta alla CSEA"]],[
  ("Stabilisci per ciascuna se è obbligata e perché.",7,"A: grande impresa, perché fatturato oltre 50 milioni e bilancio oltre 43 milioni, anche con meno di 250 occupati: obbligata. B: grande impresa per numero di occupati: obbligata. C: impresa a forte consumo iscritta alla CSEA: obbligata. D: non è grande impresa né energivora: non obbligata dal D.lgs. 102/2014.",["Ho applicato i criteri di grande impresa","Ho considerato l’iscrizione CSEA","Ho escluso correttamente l’impresa D"]),
  ("Entro quando e come si adempie?",5,"Diagnosi ogni quattro anni, eseguita da un soggetto certificato, caricata sul portale ENEA entro il 5 dicembre dell’anno d’obbligo; la prossima scadenza è il 5 dicembre 2027.",["Ho indicato la periodicità","Ho indicato il portale ENEA e il 5 dicembre","Ho indicato il 2027"]),
  ("Quale obbligo aggiuntivo ha l’impresa C?",5,"Come energivora deve attuare almeno uno degli interventi individuati nella diagnosi oppure adottare un sistema di gestione ISO 50001. La nuova direttiva introdurrà soglie basate sui consumi, da 10 TJ l’anno, quando sarà recepita.",["Ho indicato l’obbligo di attuare un intervento o la ISO 50001","Ho richiamato le soglie della nuova direttiva"])],
 "Nel laboratorio verifichi l’obbligo di diagnosi per quattro imprese. Applica i criteri di grande impresa e di impresa energivora, indica scadenze e modalità e l’obbligo aggiuntivo degli energivori, poi confronta ogni risposta con la soluzione di riferimento.","Art. 8 D.lgs. 102/2014 · Racc. 2003/361/CE")])
E(C,'M1-Z05','La nuova direttiva sull’efficienza energetica e il quadro italiano',[ES("Esempio guidato · Le soglie di 10 e 85 TJ in pratica","Dai consumi annui alle soglie della direttiva.",[
 ["I consumi","Energia elettrica 1.800 MWh; gas naturale 250.000 Sm³.","1.800 MWh · 250.000 Sm³"],
 ["Il gas in MWh","Con circa 9,6 kWh per Sm³: 250.000 × 9,6 = 2.400 MWh.","2.400 MWh"],
 ["Il totale","1.800 + 2.400 = 4.200 MWh; 1 MWh = 3,6 GJ.","4.200 × 3,6 = 15.120 GJ ≈ 15,1 TJ"],
 ["Le soglie","Oltre 10 TJ: diagnosi quadriennale; oltre 85 TJ: sistema di gestione dell’energia.","10 < 15,1 < 85"],
 ["La conclusione","Con il recepimento l’impresa sarebbe tenuta alla diagnosi, non al sistema di gestione.","Diagnosi sì · ISO 50001 no"]],
 "Applichiamo le soglie della nuova direttiva. L’impresa consuma milleottocento megawattora di elettricità e duecentocinquantamila metri cubi standard di gas, circa duemilaquattrocento megawattora. Il totale è quattromiladuecento megawattora, circa quindici terajoule. Supera i dieci terajoule, quindi sarebbe tenuta alla diagnosi; resta sotto gli ottantacinque, quindi non al sistema di gestione.","Direttiva (UE) 2023/1791, art. 11")])
E(C,'M1-Z06','Grandi imprese, energivori e imprese multisito',[LB("Laboratorio · L’impresa con molti siti","Una grande impresa di logistica ha sette siti e deve organizzare la diagnosi.",[
  ["Sito 1","magazzino refrigerato, 4.800 MWh"],["Sito 2","magazzino refrigerato, 3.100 MWh"],["Sito 3","hub di smistamento, 1.200 MWh"],["Siti 4-6","depositi, 150-300 MWh ciascuno"],["Sito 7","ufficio, 40 MWh"],["Flotta","35 veicoli pesanti di proprietà"]],[
  ("Come imposti la selezione dei siti?",6,"Si ordinano i siti per consumo e si applicano i criteri di selezione e di copertura minima delle linee guida ENEA vigenti; i siti più energivori, qui 1 e 2, vanno sempre inclusi; i siti con consumi molto bassi possono essere esclusi secondo i chiarimenti ministeriali e ENEA.",["Ho ordinato i siti per consumo","Ho richiamato i criteri ENEA","Ho incluso i siti principali"]),
  ("La flotta rientra nel perimetro? Come la tratti?",6,"Sì: la diagnosi comprende anche i trasporti. Si raccolgono consumi di carburante per veicolo, chilometri e carichi, si calcolano indicatori come litri per 100 km o per tonnellata-chilometro e si valutano interventi come formazione alla guida, rinnovo dei mezzi e ottimizzazione dei percorsi.",["Ho incluso i trasporti","Ho proposto indicatori della flotta","Ho proposto interventi"]),
  ("Quali sono i rischi di una diagnosi non conforme?",5,"Sanzioni amministrative dell’art. 16 del D.lgs. 102/2014 e obbligo di eseguire comunque una diagnosi conforme; per gli energivori, possibili effetti sulle agevolazioni legate all’iscrizione.",["Ho indicato le sanzioni dell’art. 16","Ho indicato l’obbligo di rifare la diagnosi"])],
 "Nel laboratorio organizzi la diagnosi di un’impresa di logistica con sette siti e una flotta. Imposta la selezione dei siti, tratta la flotta nel perimetro e valuta i rischi di una diagnosi non conforme, poi confronta ogni risposta con la soluzione di riferimento.","Art. 8 e art. 16 D.lgs. 102/2014 · linee guida ENEA")])
E(C,'M1-Z07','L’energy manager: art. 19 della L. 10/1991',[ES("Esempio guidato · Serve l’energy manager?","Conversione dei consumi in tonnellate equivalenti di petrolio.",[
 ["I consumi","Un’industria consuma 30.000 MWh di elettricità e 6 milioni di Sm³ di gas naturale all’anno.","30.000 MWh · 6.000.000 Sm³"],
 ["L’elettricità","Con il fattore 0,187 tep/MWh: 30.000 × 0,187 = 5.610 tep.","5.610 tep"],
 ["Il gas","Con il fattore 0,836 tep ogni 1.000 Sm³: 6.000 × 0,836 = 5.016 tep.","5.016 tep"],
 ["Il totale","5.610 + 5.016 = 10.626 tep: oltre la soglia di 10.000 tep dell’industria.","10.626 > 10.000"],
 ["L’obbligo","Nomina dell’energy manager e comunicazione alla FIRE entro il 30 aprile.","Nomina entro il 30 aprile"]],
 "Verifichiamo l’obbligo di nominare l’energy manager. Trentamila megawattora di elettricità, per zero virgola centottantasette, fanno cinquemilaseicentodieci tep. Sei milioni di metri cubi di gas, a zero virgola ottocentotrentasei tep ogni mille, fanno cinquemilasedici tep. Il totale, diecimilaseicentoventisei tep, supera la soglia di diecimila prevista per l’industria: la nomina va comunicata alla FIRE entro il trenta aprile.","Art. 19 L. 10/1991 · Circolare MiSE 18 dicembre 2014")])
E(C,'M1-Z08','La metodologia UNI CEI EN 16247',[CL("In quale fase della diagnosi?","Seleziona un’attività, poi la fase della UNI CEI EN 16247.",["Avvio","Raccolta dati e attività in campo","Analisi","Rapporto e incontro finale"],[
 ["Concordare obiettivi, perimetro e criteri di valutazione degli interventi",0,"Si definiscono nel contatto preliminare e nell’incontro di avvio."],["Installare analizzatori di rete sulle utenze significative",1,"È attività in campo."],
 ["Costruire il modello energetico e calcolare gli indicatori",2,"È analisi."],["Presentare alla direzione gli interventi prioritari",3,"Avviene nell’incontro finale."],
 ["Intervistare i responsabili di produzione sugli orari",1,"Fa parte della raccolta dati."],["Stimare risparmi e costi degli interventi",2,"È analisi."]],
 "Sei attività di una diagnosi energetica. Collocale nella fase giusta della metodologia.","UNI CEI EN 16247-1")])
E(C,'M1-Z09','Diagnosi energetica e sistema di gestione dell’energia: elementi distintivi',[LB("Laboratorio · Diagnosi o ISO 50001?","Consigli la direzione di un gruppo industriale sulla strategia energetica.",[
  ["Consumi","circa 120 TJ l’anno su due stabilimenti"],["Situazione","diagnosi eseguite nel 2019 e nel 2023, interventi attuati solo in parte"],["Obiettivi","ridurre i costi e rendicontare la sostenibilità"]],[
  ("Con la nuova direttiva che cosa sarà richiesto al gruppo?",5,"Con consumi oltre 85 TJ l’anno la direttiva prevede l’obbligo di un sistema di gestione dell’energia certificato; il sistema, se include una diagnosi conforme, esenta dalla diagnosi quadriennale.",["Ho applicato la soglia di 85 TJ","Ho indicato il sistema di gestione","Ho indicato l’esenzione"]),
  ("Quali vantaggi ha il sistema rispetto alle sole diagnosi?",6,"Gestione continua invece di una fotografia ogni quattro anni; obiettivi e indicatori annuali; responsabilità e risorse definite; audit interni e riesame; migliore attuazione degli interventi; dati affidabili per la rendicontazione di sostenibilità.",["Ho indicato la continuità","Ho indicato obiettivi e responsabilità","Ho collegato la rendicontazione"]),
  ("Proponi un percorso in tre tappe.",6,"1: analisi iniziale e politica energetica, partendo dalla diagnosi 2023; 2: piano di misura, indicatori e baseline, obiettivi e piano d’azione; 3: audit interno, riesame e certificazione di parte terza, con il primo ciclo di miglioramento.",["Ho previsto l’analisi iniziale","Ho previsto indicatori e baseline","Ho previsto audit e certificazione"])],
 "Nel laboratorio consigli la direzione di un gruppo industriale che consuma centoventi terajoule l’anno. Stabilisci che cosa richiederà la nuova direttiva, i vantaggi del sistema di gestione e un percorso in tre tappe, poi confronta ogni risposta con la soluzione di riferimento.","Direttiva (UE) 2023/1791 · UNI CEI EN ISO 50001")])
E(C,'M1-Z10','Il rapporto di diagnosi e la comunicazione all’ENEA',[LB("Laboratorio · Rivedere un rapporto di diagnosi","Fai la revisione di un rapporto di diagnosi prima del caricamento sul portale ENEA.",[
  ["Periodo","anno 2026"],["Modello energetico","solo consumi totali per vettore"],["Indicatori","consumo per addetto"],["Interventi","8 interventi elencati, senza costi né risparmi"],["Monitoraggio","non descritto"]],[
  ("Elenca le carenze del rapporto.",6,"Manca la ripartizione per aree funzionali e utenze significative; l’indicatore per addetto non rappresenta la produzione; gli interventi non hanno costi, risparmi, tempi di ritorno e priorità; manca la strategia di monitoraggio richiesta dalle linee guida ENEA.",["Ho rilevato il modello incompleto","Ho criticato l’indicatore","Ho rilevato interventi e monitoraggio mancanti"]),
  ("Quali indicatori proporresti per uno stabilimento produttivo?",5,"Consumo specifico per unità di prodotto, ad esempio MWh per tonnellata, per vettore e per area funzionale; indicatori dei servizi ausiliari, come kWh per metro cubo di aria compressa; normalizzazione rispetto a produzione e gradi giorno.",["Ho proposto il consumo specifico","Ho proposto indicatori dei servizi ausiliari","Ho previsto la normalizzazione"]),
  ("Come completeresti la scheda di un intervento?",6,"Descrizione tecnica, situazione attuale e futura, risparmio energetico ed economico annuo, investimento, tempo di ritorno, VAN e analisi del ciclo di vita, incentivi applicabili, priorità e modalità di misura e verifica.",["Ho indicato risparmi e investimento","Ho indicato gli indicatori economici","Ho previsto misura e verifica"])],
 "Nel laboratorio rivedi un rapporto di diagnosi prima del caricamento sul portale ENEA. Individua le carenze, proponi indicatori adatti e completa la scheda di un intervento, poi confronta ogni risposta con la soluzione di riferimento.","D.lgs. 102/2014, Allegato 2 · linee guida ENEA"),
 AP("La diagnosi nella tua organizzazione","Fai il punto sulla situazione energetica della tua organizzazione.",["Conosco i consumi per vettore","Esistono contatori sulle utenze principali","Abbiamo un indicatore di consumo specifico","Siamo obbligati alla diagnosi","Abbiamo nominato l’energy manager","Gli interventi della diagnosi sono monitorati"],"Il primo dato che ti manca e come lo otterresti","Es.: consumo dell’aria compressa → analizzatore di rete sul compressore per due settimane",
  "Fai il punto sulla situazione energetica della tua organizzazione e indica il primo dato che ti manca.",3)])
# ── M2 ──
E(C,'M2-Z01','Strategia di monitoraggio e modello energetico',[LB("Laboratorio · Il piano di misura","Prepari il piano di misura di uno stabilimento di stampaggio plastico.",[
  ["Contatori presenti","contatore generale elettrico; contatore gas generale"],["Utenze significative","presse a iniezione, compressori, gruppi frigo, centrale termica"],["Budget","limitato: 8 punti di misura"]],[
  ("Dove installi gli 8 punti di misura e perché?",7,"Presse a iniezione, raggruppate per linea, perché sono l’attività principale; compressori, frigo e centrale termica, perché sono servizi ausiliari significativi; un punto per i servizi generali; il resto per differenza. Priorità alle utenze con consumo maggiore e a quelle con potenziale di risparmio.",["Ho coperto le attività principali","Ho coperto i servizi ausiliari","Ho motivato le priorità"]),
  ("Quali variabili rilevanti registri insieme ai consumi?",5,"Produzione in tonnellate o pezzi, ore di funzionamento, gradi giorno per la climatizzazione, temperatura dell’acqua di raffreddamento, pressione della rete dell’aria compressa.",["Ho indicato la produzione","Ho indicato i gradi giorno","Ho indicato variabili di processo"]),
  ("Come verifichi la chiusura del bilancio?",5,"Si confronta la somma dei consumi misurati e stimati con il contatore generale: lo scostamento dovrebbe restare entro pochi punti percentuali, ad esempio sotto il 5%; se è maggiore si cercano utenze non censite o errori di stima.",["Ho confrontato con il contatore generale","Ho indicato una soglia di scostamento","Ho previsto la ricerca delle cause"])],
 "Nel laboratorio prepari il piano di misura di uno stabilimento con un budget limitato. Scegli dove misurare, quali variabili rilevanti registrare e come verificare la chiusura del bilancio, poi confronta ogni risposta con la soluzione di riferimento.","Linee guida ENEA · UNI CEI EN 16247-3")])
E(C,'M2-Z02','Baseline e indicatori di prestazione energetica (ISO 50006)',[LB("Laboratorio · Normalizzare il consumo","Uno stabilimento ha una baseline elettrica ricavata dalla regressione dei dati mensili: E = 120 MWh + 0,35 MWh/t × produzione.",[
  ["Mese in esame","produzione 900 t; consumo effettivo 470 MWh"],["Mese di confronto dell’anno precedente","produzione 700 t; consumo 365 MWh"],["Coefficiente R²","0,86"]],[
  ("Calcola il consumo atteso del mese in esame e lo scostamento.",6,"Atteso: 120 + 0,35 × 900 = 435 MWh. Scostamento: 470 − 435 = +35 MWh, circa +8%: la prestazione è peggiorata rispetto alla baseline.",["Ho calcolato 435 MWh","Ho calcolato +35 MWh","Ho interpretato il peggioramento"]),
  ("Perché il semplice confronto con l’anno precedente è fuorviante?",5,"Perché la produzione è diversa: 470 contro 365 MWh sembrerebbe un peggioramento del 29%, ma gran parte dipende dalle 200 t in più. Solo la normalizzazione separa l’effetto della produzione da quello dell’efficienza. Inoltre il consumo specifico cala con la produzione per effetto della quota fissa di 120 MWh.",["Ho spiegato l’effetto della produzione","Ho citato la quota fissa","Ho motivato la normalizzazione"]),
  ("Il modello è affidabile? Che cosa controlli?",5,"Un R² di 0,86 indica un buon adattamento; si verificano anche il numero di dati, la significatività dei coefficienti, i residui e che le condizioni del mese siano nel campo di validità del modello. Il modello va aggiornato se cambiano impianti o processi.",["Ho interpretato R²","Ho citato altri controlli statistici","Ho previsto l’aggiornamento del modello"])],
 "Nel laboratorio usi una baseline ottenuta per regressione per valutare la prestazione di un mese. Calcola il consumo atteso e lo scostamento, spiega perché il confronto semplice è fuorviante e verifica l’affidabilità del modello, poi confronta ogni risposta con la soluzione di riferimento.","UNI ISO 50006")])
E(C,'M2-Z03','Esempio applicativo: il modello energetico di uno stabilimento',[LB("Laboratorio · Il modello energetico di una cartotecnica","Costruisci il modello energetico elettrico di una cartotecnica.",[
  ["Totale annuo","1.600 MWh dal contatore generale"],["Misurati","linee di stampa 620 MWh; fustellatrici 240 MWh; aria compressa 210 MWh"],["Stimati","aspirazione rifili 180 MWh; illuminazione 150 MWh; climatizzazione uffici 70 MWh; altro 60 MWh"],["Produzione","4.000 t"]],[
  ("Ripartisci i consumi nelle tre aree funzionali con le percentuali.",6,"Attività principali, stampa e fustellatura: 860 MWh, circa 54%. Servizi ausiliari, aria compressa e aspirazione: 390 MWh, circa 24%. Servizi generali, illuminazione, climatizzazione e altro: 280 MWh, circa 18%. Totale 1.530 MWh.",["Ho raggruppato per aree funzionali","Ho calcolato le percentuali","Ho sommato 1.530 MWh"]),
  ("Verifica la chiusura del bilancio e calcola l’indicatore.",5,"Scostamento: 1.600 − 1.530 = 70 MWh, circa 4,4%: accettabile se sotto il 5%. Indicatore: 1.600 MWh / 4.000 t = 0,40 MWh/t.",["Ho calcolato lo scostamento","Ho confrontato con la soglia","Ho calcolato 0,40 MWh/t"]),
  ("Dove cercheresti per primi i risparmi?",6,"Aria compressa e aspirazione, che insieme fanno un quarto dei consumi e hanno spesso margini ampi: perdite, pressione, inverter sui ventilatori e regolazione in base all’uso. Poi l’illuminazione con LED e sensori. Infine i consumi a vuoto delle linee nelle pause.",["Ho indicato i servizi ausiliari","Ho proposto interventi concreti","Ho considerato i consumi a vuoto"])],
 "Nel laboratorio costruisci il modello energetico elettrico di una cartotecnica. Ripartisci i consumi per aree funzionali, verifica la chiusura del bilancio e calcola l’indicatore, poi individua dove cercare i risparmi. Confronta ogni risposta con la soluzione di riferimento.","UNI CEI EN 16247-3 · linee guida ENEA")])
E(C,'M2-Z04','Motori elettrici: le classi di efficienza IE',[ES("Esempio guidato · Sostituire un motore IE2 con un IE4","Il risparmio di un motore più efficiente.",[
 ["Il motore","55 kW, carico medio 75%, 6.000 ore l’anno; rendimento IE2 indicativo 93,5%.","Potenza resa 41,25 kW"],
 ["Assorbimento attuale","41,25 / 0,935 ≈ 44,1 kW.","44,1 kW"],
 ["Con IE4","Rendimento indicativo 95,8%: 41,25 / 0,958 ≈ 43,1 kW.","43,1 kW"],
 ["Il risparmio","Circa 1,0 kW × 6.000 h ≈ 6.100 kWh l’anno; a 0,20 €/kWh circa 1.220 €.","≈ 6,1 MWh · ≈ 1.220 €/anno"],
 ["La decisione","Conviene soprattutto alla sostituzione per guasto o fine vita, valutando anche l’inverter se il carico varia.","Sostituzione programmata"]],
 "Valutiamo la sostituzione di un motore da cinquantacinque chilowatt che lavora al settantacinque per cento per seimila ore. Con un rendimento indicativo del novantatré e mezzo per cento assorbe circa quarantaquattro chilowatt; con un IE quattro circa quarantatré. Il risparmio è di circa seimila chilowattora l’anno, milleduecento euro. Conviene soprattutto quando il motore va comunque sostituito, valutando anche un inverter se il carico varia.","Reg. (UE) 2019/1781 · IEC 60034-30-1")])
E(C,'M2-Z05','Aria compressa: perdite, pressione e recupero di calore',[LB("Laboratorio · La caccia alle perdite","Valuti la rete dell’aria compressa di uno stabilimento.",[
  ["Compressore","75 kW, a velocità fissa, pressione di rete 8 bar"],["Prova a impianto fermo","nel fine settimana, con produzione ferma, il compressore lavora a carico per il 35% del tempo"],["Ore annue di funzionamento della rete","6.000"],["Prezzo dell’energia","0,20 €/kWh"],["Utenza più esigente","6 bar"]],[
  ("Stima il costo annuo delle perdite.",7,"A impianto fermo il compressore alimenta solo le perdite: circa 35% di 75 kW ≈ 26 kW. Su 6.000 ore: 26 × 6.000 ≈ 158.000 kWh, circa 31.500 € l’anno.",["Ho usato la prova a impianto fermo","Ho calcolato circa 158 MWh","Ho calcolato il costo"]),
  ("Quanto vale ridurre la pressione da 8 a 7 bar?",5,"Circa 6-7% di energia per bar: sul consumo del compressore, ad esempio 300 MWh l’anno, circa 20 MWh, cioè 4.000 € l’anno, se l’utenza a 6 bar resta servita con margine.",["Ho applicato il 6-7% per bar","Ho stimato il risparmio","Ho verificato l’utenza più esigente"]),
  ("Proponi un piano d’intervento.",6,"Ricerca delle perdite con ultrasuoni e riparazione, ripetuta periodicamente; riduzione della pressione; chiusura delle linee non usate; compressore a velocità variabile o gestione coordinata; recupero di calore per acqua calda o riscaldamento; misura continua dei consumi.",["Ho previsto la ricerca periodica delle perdite","Ho previsto pressione e regolazione","Ho previsto il recupero di calore"])],
 "Nel laboratorio valuti la rete dell’aria compressa. Stima il costo delle perdite con la prova a impianto fermo, calcola il valore della riduzione di pressione e proponi un piano d’intervento, poi confronta ogni risposta con la soluzione di riferimento.","Linee guida ENEA · buone pratiche di efficienza energetica")])
E(C,'M2-Z06','Sistemi termici, recupero di calore e cogenerazione',[SC("Il calore del compressore","Un’impresa ha compressori raffreddati ad aria per 150 kW elettrici complessivi e una caldaia a gas che produce acqua calda di processo a 60 °C tutto l’anno.",[
 ("Che cosa proponi?",[["Recuperare il calore dei compressori per preriscaldare l’acqua di processo",True,"Corretto: gran parte dell’energia assorbita da un compressore diventa calore recuperabile."],["Aumentare la potenza della caldaia",False,"Aumenta i consumi."],["Raffreddare di più i compressori",False,"Spreca il calore."]]),
 ("Perché l’intervento è particolarmente adatto qui?",[["Perché c’è un’utenza termica costante tutto l’anno a temperatura compatibile",True,"Corretto: la contemporaneità tra calore disponibile e domanda decide il risparmio."],["Perché il gas è gratuito",False,"Non è così."],["Non è adatto",False,"Le condizioni sono favorevoli."]]),
 ("Come verifichi il risparmio dopo l’intervento?",[["Misurando il calore recuperato con un contatore di energia termica e il minor consumo di gas, normalizzato sulla produzione",True,"Corretto: misura e verifica con variabili normalizzate."],["Con la bolletta di un mese",False,"Non tiene conto delle variabili."],["Non serve verificare",False,"La verifica è essenziale, anche per gli incentivi."]])],
 "Calore disponibile e domanda termica contemporanea fanno del recupero dai compressori uno degli interventi più convenienti, da verificare con misure normalizzate.","Compressori e caldaia nello stesso stabilimento. Trova l’opportunità.","UNI CEI EN 16247-3 · UNI CEI EN ISO 50015")])
E(C,'M2-Z07','La cogenerazione ad alto rendimento',[ES("Esempio guidato · Il risparmio di energia primaria (PES)","Un cogeneratore a gas da 1,5 MW elettrici.",[
 ["I rendimenti","Rendimento elettrico 38%, rendimento termico utile 45%.","ηel 0,38 · ηth 0,45"],
 ["I riferimenti","Rendimenti di riferimento indicativi della produzione separata: 53% per l’elettricità, 92% per il calore.","0,53 · 0,92"],
 ["Il calcolo","PES = 1 − 1 / (0,45/0,92 + 0,38/0,53) = 1 − 1 / (0,489 + 0,717).","1 − 1/1,206"],
 ["Il risultato","PES ≈ 17%.","≈ 17%"],
 ["La qualifica","Sopra 1 MW serve un PES di almeno il 10%: l’unità è ad alto rendimento, a condizione che il calore sia utilmente impiegato.","CAR se il calore è usato"]],
 "Calcoliamo il risparmio di energia primaria di un cogeneratore da un megawatt e mezzo. Con rendimento elettrico del trentotto per cento e termico del quarantacinque, e riferimenti indicativi del cinquantatré e del novantadue per cento, il PES vale circa diciassette per cento. Sopra un megawatt serve almeno il dieci: l’unità è ad alto rendimento, purché il calore sia davvero utilizzato.","D.lgs. 20/2007 · D.M. 4 agosto 2011 · Reg. delegato (UE) 2015/2402")])
E(C,'M2-Z08','VAN, TIR e tempo di ritorno',[LB("Laboratorio · Valutare un intervento con VAN e TIR","Valuti un intervento di efficienza per la direzione.",[
  ["Investimento","40.000 €"],["Risparmio annuo netto","9.000 €"],["Vita utile","8 anni"],["Tasso di attualizzazione","6%"],["Fattore di attualizzazione di una rendita a 8 anni al 6%","6,210"]],[
  ("Calcola il tempo di ritorno semplice.",4,"40.000 / 9.000 ≈ 4,4 anni.",["Ho diviso investimento per risparmio","Ho ottenuto circa 4,4 anni"]),
  ("Calcola il VAN e interpretalo.",7,"Valore attuale dei risparmi: 9.000 × 6,210 = 55.890 €. VAN = 55.890 − 40.000 = 15.890 €. Essendo positivo, l’intervento crea valore al tasso del 6%.",["Ho attualizzato i risparmi","Ho calcolato circa 15.900 €","Ho interpretato il segno del VAN"]),
  ("Stima il TIR e formula una raccomandazione.",6,"Il TIR è il tasso per cui il valore attuale dei risparmi è 40.000 €, cioè fattore di rendita 4,44: a 8 anni corrisponde a circa il 15%. È ben superiore al 6%: l’intervento è raccomandabile, verificando incentivi, manutenzione e incertezza dei risparmi.",["Ho impostato il TIR","Ho stimato circa il 15%","Ho formulato una raccomandazione"])],
 "Nel laboratorio valuti economicamente un intervento di efficienza. Calcola il tempo di ritorno, il valore attuale netto e una stima del tasso interno di rendimento, poi formula una raccomandazione. Confronta ogni risposta con la soluzione di riferimento.","UNI CEI EN 16247-1 · D.lgs. 102/2014, Allegato 2")])
E(C,'M2-Z09','Esempio applicativo: inverter su una pompa',[SC("Il fornitore che promette il 50%","Un fornitore propone inverter su tutte le pompe dello stabilimento promettendo «almeno il 50% di risparmio».",[
 ("Che cosa verifichi prima?",[["Se le pompe lavorano a carico variabile o sono regolate con valvole di strozzamento",True,"Corretto: l’inverter rende quando la portata richiesta varia."],["Solo il prezzo",False,"Il risparmio dipende dal funzionamento."],["Niente, la promessa è scritta",False,"Va verificata con misure."]]),
 ("Una pompa lavora sempre a portata costante e nominale. Conviene l’inverter?",[["Poco o nulla: senza riduzione di velocità non c’è risparmio, e l’inverter ha perdite proprie",True,"Corretto."],["Sì, sempre il 50%",False,"Non è così."],["Sì, perché riduce la potenza installata",False,"La potenza assorbita dipende dal punto di lavoro."]]),
 ("Come imposti la valutazione corretta?",[["Misure di potenza e portata per alcune settimane, stima con le leggi di affinità e piano di misura e verifica",True,"Corretto."],["Una sola lettura al mattino",False,"Non rappresenta il profilo."],["La scheda del fornitore",False,"Va verificata."]])],
 "Le leggi di affinità promettono molto solo dove la portata varia: misure, stima e verifica separano gli interventi utili da quelli venduti con promesse generiche.","Una proposta commerciale molto ottimista. Valutala con metodo.","Leggi di affinità · UNI CEI EN ISO 50015")])
E(C,'M2-Z10','Titoli di efficienza energetica e incentivi',[CL("Quale strumento?","Seleziona un intervento, poi lo strumento di incentivazione tipico.",["Certificati bianchi","Conto termico","Autoconsumo e comunità energetiche"],[
 ["Risparmio misurato su un processo industriale con un progetto a consuntivo",0,"I certificati bianchi premiano risparmi addizionali misurati."],["Sostituzione di una caldaia con una pompa di calore in un edificio",1,"È un intervento tipico del conto termico."],
 ["Impianto fotovoltaico condiviso con imprese vicine",2,"Rientra negli incentivi per l’autoconsumo diffuso."],["Solare termico per l’acqua calda sanitaria",1,"Produzione di energia termica da rinnovabili."],
 ["Recupero di calore da un forno industriale",0,"Risparmio industriale misurabile."],["Configurazione di autoconsumo collettivo in un condominio",2,"È autoconsumo collettivo."]],
 "Sei interventi. Indica lo strumento di incentivazione tipicamente collegato, ricordando di verificare sempre i requisiti dei bandi vigenti.","GSE · D.M. 21 dicembre 2017 · D.M. 7 dicembre 2023")])
E(C,'M2-Z11','Misura e verifica dei risparmi (ISO 50015 e ISO 50047)',[LB("Laboratorio · Il piano di misura e verifica","Prepari il piano di misura e verifica per l’installazione di un inverter sul ventilatore di un forno.",[
  ["Prima dell’intervento","3 mesi di misure: assorbimento medio 30 kW, produzione 500 t al mese"],["Dopo l’intervento","3 mesi di misure: assorbimento medio 21 kW, produzione 560 t al mese"],["Ore di funzionamento","500 al mese, invariate"]],[
  ("Definisci confine di misura, periodi e variabili.",5,"Confine: il ventilatore del forno con il suo azionamento. Periodo di riferimento: tre mesi prima; periodo di rendicontazione: tre mesi dopo. Variabili: produzione e ore di funzionamento; fattori statici: configurazione del forno.",["Ho definito il confine","Ho definito i periodi","Ho indicato variabili e fattori statici"]),
  ("Calcola il risparmio mensile normalizzato, ipotizzando che il consumo del ventilatore cresca in proporzione alla produzione.",7,"Consumo di riferimento normalizzato: 30 kW × 500 h × 560/500 = 16.800 kWh. Consumo effettivo: 21 × 500 = 10.500 kWh. Risparmio: 6.300 kWh al mese. Senza normalizzazione si sarebbe stimato 4.500 kWh: la normalizzazione cambia il risultato.",["Ho normalizzato sulla produzione","Ho calcolato 6.300 kWh","Ho confrontato con il valore non normalizzato"]),
  ("Come dichiari l’incertezza e documenti il risultato?",5,"Si indicano la precisione degli strumenti, la rappresentatività dei periodi e l’ipotesi di proporzionalità; si documentano dati, metodo e aggiustamenti in un rapporto coerente con la ISO 50015, utile anche per eventuali incentivi.",["Ho indicato le fonti di incertezza","Ho documentato metodo e aggiustamenti"])],
 "Nel laboratorio prepari il piano di misura e verifica di un inverter su un ventilatore. Definisci confine, periodi e variabili, calcola il risparmio normalizzato e indica come dichiarare l’incertezza, poi confronta ogni risposta con la soluzione di riferimento.","UNI CEI EN ISO 50015 · ISO 50047"),
 AP("Il tuo primo intervento di efficienza","Scegli l’intervento da proporre per primo nella tua organizzazione.",["Ricerca delle perdite di aria compressa","Riduzione della pressione di rete","Inverter su pompe e ventilatori","Illuminazione LED con sensori","Recupero di calore","Spegnimento delle utenze a vuoto","Piano di misura sulle utenze significative"],"L’intervento scelto, il risparmio atteso e come lo verificherai","Es.: ricerca perdite, 15% dell’energia dei compressori, verifica con prova a impianto fermo",
  "Scegli il primo intervento di efficienza da proporre nella tua organizzazione e indica risparmio atteso e modalità di verifica.",3)])
E(C,'M1-Z11','La metodologia UNI CEI EN 16247',[LB("Laboratorio · Pianificare la diagnosi","Sei l’EGE incaricato della diagnosi di uno stabilimento alimentare obbligato, con scadenza il 5 dicembre 2027.",[
  ["Stabilimento","produzione di sughi pronti, 3 turni, cottura a vapore, celle frigorifere, linee di confezionamento"],["Dati disponibili","bollette mensili, un contatore sulla centrale frigorifera"],["Incarico","firmato a febbraio 2027"]],[
  ("Prepara il calendario delle fasi con i mesi indicativi.",6,"Febbraio: incontro di avvio con obiettivi, perimetro e criteri economici. Marzo-maggio: raccolta dati e campagna di misure su vapore, frigo, aria compressa e linee. Giugno-agosto: modello energetico, indicatori, interventi. Settembre: rapporto e incontro finale. Ottobre-novembre: margine per correzioni e caricamento sul portale ENEA prima del 5 dicembre.",["Ho seguito le fasi della norma","Ho previsto una campagna di misure","Ho lasciato margine prima della scadenza"]),
  ("Quali dati e documenti chiedi all’impresa?",6,"Consumi per vettore dell’anno di riferimento con profili orari elettrici; dati di produzione mensili; schemi degli impianti e potenze; ore di funzionamento; contratti di fornitura; interventi già realizzati; eventuali diagnosi precedenti.",["Ho chiesto consumi e profili","Ho chiesto dati di produzione","Ho chiesto dati impiantistici"]),
  ("Quali utenze misuri durante la campagna e perché?",5,"Generatore di vapore e utenze di cottura, celle frigorifere e compressori frigoriferi, aria compressa, linee di confezionamento: sono le utenze significative di un’industria alimentare e dove si concentrano i risparmi.",["Ho individuato le utenze termiche","Ho individuato il freddo","Ho motivato la scelta"])],
 "Nel laboratorio pianifichi una diagnosi in uno stabilimento alimentare. Prepara il calendario delle fasi, la richiesta di dati e la campagna di misure, poi confronta ogni risposta con la soluzione di riferimento.","UNI CEI EN 16247-1 e 16247-3")])
E(C,'M1-Z12','L’obbligo di diagnosi energetica (art. 8 D.lgs. 102/2014)',[SC("La scadenza dimenticata","A metà dicembre un’impresa a forte consumo di energia scopre di non aver caricato la diagnosi sul portale ENEA entro il 5 dicembre.",[
 ("Che cosa fa subito?",[["Completa la diagnosi con un soggetto certificato e la carica al più presto, documentando il ritardo",True,"Corretto: l’obbligo resta e il ritardo va sanato."],["Aspetta la prossima scadenza fra quattro anni",False,"L’obbligo non si sposta."],["Carica la diagnosi precedente",False,"Non è conforme."]]),
 ("A che cosa si espone l’impresa?",[["Alle sanzioni amministrative dell’art. 16 e ai controlli ENEA, con l’obbligo di eseguire comunque la diagnosi",True,"Corretto."],["A nulla",False,"Le sanzioni sono previste."],["Solo a un richiamo verbale",False,"Le sanzioni sono pecuniarie."]]),
 ("Come evita che succeda di nuovo?",[["Scadenzario con avvio dell’incarico almeno un anno prima e un responsabile interno",True,"Corretto: la diagnosi richiede mesi di lavoro."],["Un promemoria il 1° dicembre",False,"Troppo tardi."],["Delegare tutto al consulente senza controllo",False,"La responsabilità resta dell’impresa."]])],
 "La diagnosi richiede mesi: chi la avvia per tempo rispetta la scadenza, chi la dimentica deve sanare il ritardo e si espone alle sanzioni.","Una scadenza ENEA mancata. Gestisci le conseguenze.","Artt. 8 e 16 D.lgs. 102/2014")])
E(C,'M1-Z13','Grandi imprese, energivori e imprese multisito',[SC("L’energivora e gli interventi","Un’impresa iscritta alla CSEA ha consegnato la diagnosi con dodici interventi, ma non ne ha realizzato nessuno.",[
 ("È in regola?",[["No: l’impresa energivora deve attuare almeno uno degli interventi individuati oppure adottare un sistema ISO 50001",True,"Corretto."],["Sì, la diagnosi basta",False,"Per le energivore c’è un obbligo ulteriore."],["Sì, se gli interventi sono costosi",False,"Non è un’esimente."]]),
 ("Quale intervento sceglieresti di attuare per primo?",[["Uno con tempo di ritorno breve, risparmio verificabile e basso rischio tecnico",True,"Corretto: ad esempio perdite dell’aria compressa o inverter."],["Il più costoso, per dimostrare impegno",False,"Non è un criterio."],["Uno qualsiasi, senza misure",False,"Il risparmio va dimostrato."]]),
 ("Come lo dimostri?",[["Con un piano di misura e verifica e la documentazione dell’intervento",True,"Corretto."],["Con una dichiarazione del fornitore",False,"Non basta."],["Non serve dimostrarlo",False,"Va documentato."]])],
 "Per le imprese energivore la diagnosi non basta: almeno un intervento va realizzato e documentato, oppure va adottato un sistema di gestione certificato.","Un’impresa energivora che non ha attuato nulla. Valuta e decidi.","Art. 8, c. 3, D.lgs. 102/2014")])
E(C,'M1-Z14','La metodologia UNI CEI EN 16247',[CL("Variabile rilevante o fattore statico?","Seleziona un elemento, poi la colonna.",["Variabile rilevante","Fattore statico"],[
 ["Tonnellate prodotte al mese",0,"Cambia di routine e influenza il consumo."],["Gradi giorno di riscaldamento",0,"Variano con il clima."],
 ["Superficie riscaldata dello stabilimento",1,"Di norma non cambia: se cambia, si aggiusta la baseline."],["Numero di turni di lavoro stabilito",1,"È una condizione stabile; se cambia serve un aggiustamento."],
 ["Ore di funzionamento delle linee",0,"Variano e influenzano il consumo."],["Tipologia di prodotto realizzato",1,"Se il mix cambia radicalmente serve un aggiustamento."]],
 "Sei elementi che influenzano i consumi. Distingui le variabili rilevanti dai fattori statici.","UNI ISO 50006")])
E(C,'M2-Z12','Sistemi elettrici: motori, inverter, rifasamento, aria compressa',[SC("L’illuminazione del magazzino","Un magazzino di 4.000 m² ha lampade a scarica accese 24 ore su 24; è frequentato solo a tratti dai carrellisti.",[
 ("Quale intervento proponi?",[["Apparecchi LED con sensori di presenza e regolazione in base alla luce naturale",True,"Corretto: riduce potenza e ore di accensione."],["Spegnere tutto di notte",False,"I carrellisti lavorano anche di notte."],["Lampade più potenti",False,"Aumentano i consumi."]]),
 ("Come stimi il risparmio?",[["Potenza attuale e futura, ore di accensione effettive stimate con i sensori, prezzo dell’energia",True,"Corretto: si stimano sia la riduzione di potenza sia quella delle ore."],["Con la potenza nominale e basta",False,"Le ore contano quanto la potenza."],["Con la bolletta di un mese",False,"Non separa l’illuminazione."]]),
 ("Che cosa verifichi per la sicurezza?",[["Che l’illuminamento rispetti i valori necessari per i compiti e l’illuminazione di emergenza",True,"Corretto: l’efficienza non deve ridurre la sicurezza."],["Nulla",False,"L’illuminazione è anche un requisito di sicurezza."],["Solo il colore della luce",False,"Non basta."]])],
 "LED, sensori e regolazione riducono potenza e ore; la stima va fatta su entrambe e la sicurezza visiva va sempre verificata.","Un magazzino illuminato giorno e notte. Proponi l’intervento.","UNI EN 12464-1 · Allegato IV D.lgs. 81/2008")])
E(C,'M2-Z13','Sistemi elettrici: motori, inverter, rifasamento, aria compressa',[CL("Quale legge di affinità?","Seleziona una grandezza, poi come varia con la velocità di una pompa centrifuga.",["Proporzionale alla velocità","Al quadrato della velocità","Al cubo della velocità"],[
 ["Portata",0,"Q è proporzionale a n."],["Prevalenza",1,"H è proporzionale a n²."],["Potenza assorbita",2,"P è proporzionale a n³."],
 ["Con velocità all’80%: la potenza scende a circa il 51%",2,"0,8³ ≈ 0,51."],["Con velocità all’80%: la prevalenza scende al 64%",1,"0,8² = 0,64."],["Con velocità all’80%: la portata scende all’80%",0,"Varia linearmente."]],"Sei relazioni tra velocità e grandezze di una pompa centrifuga. Collocale nella legge di affinità corretta.","Leggi di affinità delle turbomacchine"),
 VF("Ripasso · Efficienza industriale",[["Ridurre la pressione dell’aria compressa di 1 bar fa risparmiare circa il 6-7% dell’energia del compressore.",True,"Vero."],["Il tempo di ritorno semplice tiene conto del valore del denaro nel tempo.",False,"Falso: lo fa il VAN."],["Un cogeneratore oltre 1 MW è ad alto rendimento con un PES di almeno il 10%.",True,"Vero."],["L’inverter fa risparmiare anche su una pompa sempre a portata nominale.",False,"Falso: senza riduzione di velocità il risparmio è nullo o minimo."]],"Ripasso: quattro affermazioni sull’efficienza industriale.","D.lgs. 102/2014 · UNI CEI EN 16247")])
E(C,'M1-Z15','Che cos’è una diagnosi energetica',[LB("Laboratorio · La diagnosi della flotta","Analizzi i consumi della flotta di un’impresa di trasporti nell’ambito della diagnosi.",[
  ["Flotta","35 veicoli pesanti"],["Percorrenza annua","3.150.000 km"],["Gasolio","1.008.000 litri"],["Veicolo 12","62.000 km, 23.600 litri"],["Prezzo indicativo","1,70 € al litro"]],[
  ("Calcola l’indicatore medio della flotta e quello del veicolo 12.",5,"Flotta: 1.008.000 / 3.150.000 × 100 = 32 litri per 100 km. Veicolo 12: 23.600 / 62.000 × 100 ≈ 38 litri per 100 km, circa il 19% in più della media.",["Ho calcolato 32 l/100 km","Ho calcolato circa 38 l/100 km","Ho confrontato con la media"]),
  ("Quali cause indaghi per il veicolo 12?",6,"Stile di guida, percorsi e carichi diversi dagli altri, manutenzione e pressione degli pneumatici, età e classe del veicolo, tempi di minimo con motore acceso. Prima di concludere si confrontano veicoli con missioni simili.",["Ho considerato guida e manutenzione","Ho considerato missioni e carichi","Ho previsto confronti omogenei"]),
  ("Stima il beneficio di una riduzione del 5% dei consumi con formazione alla guida e telematica.",6,"5% di 1.008.000 litri = 50.400 litri l’anno; a 1,70 € circa 85.700 €. Con circa 3,15 kg di CO₂ per kg di gasolio e una densità di circa 0,835 kg/l, cioè circa 2,63 kg di CO₂ per litro, la riduzione vale circa 133 t CO₂ l’anno.",["Ho calcolato 50.400 litri","Ho calcolato il risparmio economico","Ho stimato le emissioni evitate"])],
 "Nel laboratorio analizzi i consumi di una flotta di trentacinque veicoli pesanti. Calcola gli indicatori, individua le cause dell’anomalia di un veicolo e stima il beneficio di una riduzione dei consumi, poi confronta ogni risposta con la soluzione di riferimento.","UNI CEI EN 16247-4 · D.lgs. 102/2014")])
